:root {
    --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --font-weight-normal: 400;
    --font-weight-bold: 600;
    --font-size-body: 14px;
    --font-size-label: 14px;
    --font-size-test-notice: 13px;
    --font-size-input: 15px;
    --font-size-header: 24px;
    --font-size-paragraph: 15px;
    --font-size-link: 14px;
    --font-size-error: 13px;
    --font-size-html-h1: 28px;
    --font-size-html-h2: 20px;
    --font-size-html-h3: 16px;
    --font-size-html-h4: 14px;
    --font-size-html-h5: 12px;
    --font-size-html-h6: 10px;
    --font-size-subheader: 15px;

    /* Colors */
    --color-background: #f8fafc;
    --color-card-bg: #ffffff;
    --color-card-border: #e2e8f0;
    --color-card-shadow: rgba(0, 0, 0, 0.05);
    --color-header: #0f172a;
    --color-header-subtext: #475569;
    --color-label: #1e293b;
    --color-input-text: #1e293b;
    --color-html-text: #475569;
    --color-link: #64748b;
    --color-focus-border: #2563eb;
    --color-submit-btn-bg: #2563eb;
    --color-submit-btn-text: #ffffff;
    --color-html-link: #2563eb;
    --color-clear-button-bg: #cbd5e1;
    --color-test-notice-text: #ef4444;
    --color-test-notice-bg: #fef2f2;
    --color-test-notice-border: #fca5a5;
    --color-error: #ef4444;                 
    --color-required: #ef4444;              

    /* Border Radii */
    --border-radius-card: 12px;
    --card-border-radius: 12px;
    --border-radius-input: 8px;
    --border-radius-clear-btn: 50%;

    /* Spacing */
    --padding-container-top: 40px;
    --padding-card: 30px;
    --card-padding: 30px;
    --padding-test-notice-vertical: 12px;
    --padding-test-notice-horizontal: 20px;
    --margin-bottom-card: 20px;
    --card-margin-bottom: 20px;
    --padding-form-input: 12px 16px;

    /* Dimensions */
    --container-width: 600px;
    --submit-btn-height: 48px;
    --checkbox-size: 18px;

    /* Others */
    --box-shadow-card: 0px 4px 6px -1px var(--color-card-shadow), 0px 2px 4px -1px rgba(0, 0, 0, 0.03);
    --opacity-placeholder: 0.4;
}

